{
  "title": "Yearly Rainfall Summary",
  "body": "<div class="card">
  <figure>
    <ml-embed ref="@tool:3fa9c21:out"></ml-embed>
    <figcaption>Monthly rainfall (mm) over one year. Bars show each month's precipitation; the three wettest months are listed below.</figcaption>
  </figure>
  <section class="stats">
    <h2>Three wettest months</h2>
    <ol id="wettest"></ol>
    <p id="total" class="total"></p>
  </section>
</div>",
  "css": ".card { font-family: system-ui, -apple-system, sans-serif; max-width: 580px; margin: 0 auto; padding: 18px; background: #ffffff; border: 1px solid #e3e6ea; border-radius: 14px; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
figure { margin: 0; }
ml-embed { display: block; }
ml-embed img { max-width: 100%; height: auto; border-radius: 8px; display: block; margin: 0 auto; }
figcaption { font-size: 0.85rem; color: #5f6b7a; text-align: center; margin-top: 10px; line-height: 1.4; }
.stats { margin-top: 16px; border-top: 1px solid #edf0f3; padding-top: 12px; }
.stats h2 { font-size: 1rem; margin: 0 0 8px; color: #1a5276; }
#wettest { margin: 0; padding-left: 22px; }
#wettest li { padding: 3px 0; color: #2c3e50; }
.total { margin: 12px 0 0; font-weight: 600; color: #1a5276; background: #eaf3fa; border-radius: 8px; padding: 8px 12px; }
.error { color: #b03a2e; font-size: 0.9rem; }",
  "scripts": [
    "const fmt = n => {
  const r = Math.round(n * 10) / 10;
  return Number.isInteger(r) ? String(r) : r.toFixed(1);
};
const list = root.querySelector('#wettest');
const totalEl = root.querySelector('#total');
try {
  const csv = ml.dereference('@tool:7be01d4:out');
  const rows = csv.trim().split(/\r?\n/).slice(1).map(line => {
    const parts = line.split(',');
    return { month: (parts[0] ?? '').trim(), mm: Number(parts[1]) };
  }).filter(r => r.month.length > 0 && Number.isFinite(r.mm));
  const top3 = rows.slice().sort((a, b) => b.mm - a.mm).slice(0, 3);
  const total = rows.reduce((s, r) => s + r.mm, 0);
  list.replaceChildren();
  top3.forEach(r => {
    const li = root.create('li');
    li.textContent = r.month + ' — ' + fmt(r.mm) + ' mm';
    list.append(li);
  });
  totalEl.textContent = 'Yearly total: ' + fmt(total) + ' mm across ' + rows.length + ' months.';
} catch (e) {
  totalEl.textContent = 'Could not compute statistics from the CSV data.';
  totalEl.classList.add('error');
}"
  ]
}
